"""Law practice: published rules checked 2026-10-17, not future-law assertions."""
import math
from prediction_content import item as Q, number as N, choose

RULES_URL='https://www.meti.go.jp/policy/safety_security/industrial_safety/law/files/dengikaishaku.pdf'
VOLTAGE_URL='https://laws.e-gov.go.jp/law/409M50000400052'
SMALL_URL='https://www.safety-kanto.meti.go.jp/electric/e_syoukibo.html'

def paper(r):
    out=[]
    def add(label,cases): out.append((label,choose(r,cases)))
    add('1',[
      Q('電気事業法','低圧の電線路に接続された出力15kWの太陽電池発電設備を単独で設置する。構内外の他の電気工作物との接続などに関する特別な条件はない。この設備の区分として適切なものはどれか。','小規模事業用電気工作物。',['出力に関係なくすべて一般用電気工作物。','発電所はすべて特別高圧電気工作物。','太陽電池なので電気工作物ではない。','必ず出力500kW以上の発電設備と同じ区分。'],'単独設置などの所定条件の下では、10kW以上50kW未満の太陽電池発電設備は小規模事業用電気工作物に分類される。15kWはこの範囲に入る。'),
      Q('電気事業法','低圧受電電線路に接続する出力5kWの風力発電設備を単独で設置する。構内外の他設備との接続による特別な分類変更はない。現在の制度について適切なものはどれか。','20kW未満でも、小規模事業用電気工作物として基礎情報の届出等の対象となる。',['20kW未満なら電気事業法は一切適用されない。','風力は出力によらず電気工作物に該当しない。','低圧接続なら使用開始前の手続は常に不要である。','出力5kWなら原子力設備と同じ手続だけを行う。'],'2023年3月施行の制度で、所定条件の20kW未満の風力も小規模事業用電気工作物に位置付けられた。基礎情報や使用前自己確認などの手続を確認する。'),
      Q('電気事業法','小規模事業用電気工作物に該当する太陽電池発電設備を新設する。基礎情報の届出時期について最も適切なものはどれか。','使用の開始前までに届け出る。',['運転開始から10年後に初めて届け出る。','設置者が任意に選ぶ時期で、使用開始後でよい。','故障した場合だけ届け出る。','設備廃止後だけ届け出る。'],'新設する小規模事業用電気工作物の基礎情報は使用開始前の届出が必要である。経過措置の期間と、新設時の手続を混同しない。')])
    add('2',[
      Q('技術基準','電気設備技術基準の電圧区分で、交流600Vはどれに該当するか。','低圧。',['高圧。','特別高圧。','直流と同じ場合だけ高圧。','どの区分にも該当しない。'],'交流600V以下は低圧。600Vを超え7000V以下が高圧である。「以下」なので境界の600Vを含む。'),
      Q('技術基準','電気設備技術基準の電圧区分で、直流750Vはどれに該当するか。','低圧。',['高圧。','特別高圧。','交流と同じ600V基準なので必ず特別高圧。','電圧区分は存在しない。'],'直流750V以下は低圧。交流の低圧上限600Vとは異なるので、交流・直流の別を確認する。'),
      Q('技術基準','電気設備技術基準の電圧区分で、交流7000Vはどれに該当するか。','高圧。',['低圧。','特別高圧。','ちょうど7000Vは定義の対象外。','電力が小さければ必ず低圧。'],'交流600Vを超え7000V以下は高圧。特別高圧は7000Vを超えるものなので、境界の7000Vは高圧となる。')])
    add('3',[
      N('接地・絶縁','A種接地工事について、特例を用いない原則的な接地抵抗値の上限は何Ωか。',10,[1,50,100,500],'Ω','A種接地工事の接地抵抗値は原則10Ω以下。接地工事の種類によって基準が異なる。'),
      N('接地・絶縁','C種接地工事について、地絡時の自動遮断装置による緩和などの特例を用いない原則的な接地抵抗値の上限は何Ωか。',10,[1,50,100,500],'Ω','C種接地工事は原則10Ω以下。条件を満たす自動遮断装置などによる緩和があるが、本問ではその特例を使わない。'),
      N('接地・絶縁','D種接地工事について、地絡時の自動遮断装置による緩和などの特例を用いない原則的な接地抵抗値の上限は何Ωか。',100,[1,10,50,500],'Ω','D種接地工事は原則100Ω以下。A種・C種の10Ω以下と区別する。本問では緩和の特例は適用しない。')])
    add('4',[
      Q('接地・絶縁','電気設備技術基準の解釈に基づき、最大使用電圧23kVの通常の受電用変圧器に交流電圧を加える方法で絶縁耐力試験を行う。特例や別の試験法は用いない。適切な組合せはどれか。','28.75kVを連続10分間。',['23kVを連続1分間。','25.3kVを連続1分間。','28.75kVを連続1分間。','34.5kVを連続10分間。'],'7000Vを超え60000V以下の該当区分では、最大使用電圧の1.25倍を連続10分間。23×1.25=28.75kVとなる。'),
      Q('接地・絶縁','高圧機器の金属製外箱への保護接地の目的として、最も適切なものはどれか。','絶縁故障時の外箱の危険な電位上昇を抑え、保護装置の動作にもつなげる。',['正常時の負荷電流をすべて外箱へ流す。','接地をすれば絶縁劣化は一切発生しなくなる。','どの設備でも遮断器を不要にする。','金属外箱を電源の高圧相へ直接接続する。'],'保護接地は感電などの危険の低減に関係する。絶縁・遮断・接地を組み合わせて保護するもので、接地だけで全ての危険をなくすわけではない。'),
      Q('接地・絶縁','絶縁抵抗の測定に関する基本的な考え方として最も適切なものはどれか。','測定対象や接続機器を確認し、適切な測定電圧と保安手順を選ぶ。',['電子機器がつながったままでも、どの測定電圧でも損傷しない。','通電状態で無条件に抵抗計を接続する。','測定値は湿度や温度に全く影響されない。','絶縁抵抗が低下しても漏れ電流は一切変化しない。'],'測定器の電圧で電子機器などを損傷させないよう対象と条件を確認する。停止・検電・放電など設備に応じた安全手順が必要で、測定環境も結果に影響する。')])
    add('5',[
      N('電線路・配線','地中電線を直接埋設式で施設する。車両その他の重量物の圧力を受けるおそれがある場所で、ケーブル種類や耐圧構造による特例などを用いない。原則的な埋設深さの下限は何mか。',1.2,[.3,.6,.9,2.4],'m','直接埋設式では、重量物の圧力を受けるおそれがある場所は原則1.2m以上。例外条件を満たす施設方法とは区別する。'),
      N('電線路・配線','地中電線を直接埋設式で施設する。重量物の圧力を受けるおそれがない場所で、施設条件による特例を用いない。原則的な埋設深さの下限は何mか。',.6,[.1,.2,.3,1.2],'m','直接埋設式で、重量物の圧力を受けるおそれがある場所の1.2m以上に対し、その他の場所は原則0.6m以上。'),
      Q('電線路・配線','地中電線路を暗きょ式で施設する場合の火災対策として、電気設備技術基準の解釈に沿う組合せはどれか。','地中電線に耐燃措置を施すか、暗きょ内に自動消火設備を施設する。',['暗きょの照度だけを上げればよい。','絶縁体を除去して裸線にする。','接地線を必ずすべて切り離す。','換気扇を設ければ他の条件は一切不要になる。'],'重量物の圧力に耐える暗きょを用いることに加え、電線の耐燃措置又は暗きょ内の自動消火設備を要求する規定がある。耐熱措置や換気装置と混同しない。')])
    add('6',[
      Q('系統連系','分散型電源の逆変換装置について、直流流出を防ぐ変圧器の省略条件の一つとして、直流を検出したときに必要な機能はどれか。','交流出力を停止する機能。',['直流を検出しても交流出力を必ず最大にする機能。','保護装置を自動で取り外す機能。','系統周波数を0Hzへ固定する機能。','直流電路を必ず手で短絡する機能。'],'交流出力側で直流を検出し、その際に交流出力を停止する機能が条件の一つ。非接地式直流電路又は高周波変圧器など、他の条件も併せて満たす必要がある。'),
      Q('技術基準','事業用電気工作物の運転を管理する電子計算機のサイバーセキュリティ確保に関する規定で、除外される区分はどれか。','小規模事業用電気工作物。',['すべての自家用電気工作物。','すべての特別高圧設備。','すべての発電用設備。','すべての需要設備。'],'規定の対象は小規模事業用電気工作物を除く事業用電気工作物の運転を管理する電子計算機。除外は自家用全体ではない。'),
      Q('系統連系','系統連系する分散型電源によって短絡容量が増し、他者の遮断器容量を上回るおそれがある。適用される例外がない場合、設置者側の対策として適切なものはどれか。','限流リアクトルなど、短絡電流を制限する装置を施設する。',['遮断器の銘板の数値だけを書き換える。','他者の保護装置を無断で短絡する。','電線の許容電流は事故時だけ無限大とみなす。','短絡電流を増やせば必ず問題がなくなる。'],'分散型電源により他の設備の遮断容量や瞬時許容電流を超えるおそれには、設置者側で限流などの対策が必要。適用条件と例外は原規定で確認する。')])
    add('7',[
      Q('発電設備','風車の技術基準における、負荷遮断時の最大速度と風圧に対する要求として適切なものはどれか。','構造上安全であること。',['意図的に倒壊すること。','風圧による荷重を常に0とみなすこと。','負荷を遮断しても回転速度は絶対に変わらないとみなすこと。','電気出力だけを満たせば構造は問わないこと。'],'風車は負荷遮断時の最大速度や風圧に対して構造上安全でなければならない。発電性能だけでなく機械的安全も要求される。'),
      Q('発電設備','風車の運転中の振動について、技術基準に沿う考え方はどれか。','風車に損傷を与えるような振動がないように施設する。',['どのような振動でも損傷と無関係とみなす。','振動が大きいほど常に安全性が高い。','電圧が定格なら機械的振動は確認不要である。','故障で振動が増えても永久に運転を継続する。'],'損傷につながる運転中の振動を防ぐよう、構造・設置・運転状態に配慮する。単にすべての微小な振動を0とするという意味ではない。'),
      Q('発電設備','通常想定される最大風速時の風車の起動について、技術基準に沿うものはどれか。','取扱者の意図に反して起動しないように施設する。',['どのような条件でも必ず自動起動し続ける。','安全上の停止機能は必ず取り外す。','回転部が他の工作物へ接触してもよい。','最大風速時だけ構造上の安全を無視してよい。'],'高風速などの条件で意図しない起動を防ぐことが求められる。運転中に他の工作物や植物へ接触しない構成などと併せて安全を確保する。')])
    add('8',[
      Q('電気事業法','第三種電気主任技術者免状の保安監督範囲に関する基本的な説明として適切なものはどれか。','電圧5万V未満の事業用電気工作物で、出力5000kW以上の発電所を除く。',['すべての電圧・すべての出力の発電所を無制限に扱える。','電圧5万V以上に限って扱える。','家庭用の低圧設備だけに限られる。','原子力設備の設計資格と同じものである。'],'第三種の範囲には電圧と発電所出力の制限がある。電圧は5万V「未満」、発電所は出力5000kW「以上」を除くという境界を確認する。'),
      Q('電気事業法','第三種電気主任技術者の範囲について、電圧の条件以外は範囲内とする場合、50000Vの設備の扱いはどれか。','「5万V未満」の条件を満たさない。',['50000Vは必ず50000V未満に含まれる。','電圧が整数なら上限は適用されない。','出力0kWなら電圧制限は必ずなくなる。','電流の大きさだけで電圧区分が変わる。'],'「未満」は境界値を含まない。50000Vちょうどは、第三種の基本的な電圧範囲である50000V未満には入らない。'),
      Q('電気事業法','第三種電気主任技術者の範囲について、電圧が範囲内であっても、出力5000kWの発電所を基本範囲に含めてよいか。','出力5000kW以上の発電所は除かれるため、含めない。',['5000kWちょうどは必ず含まれる。','5000kWは5kWと同じなので含まれる。','直流設備なら出力条件は存在しない。','発電所という名称を変えれば必ず含まれる。'],'発電所出力については5000kW「以上」を除外する。電圧条件だけを満たせばよいというわけではない。')])
    add('9',[
      Q('保安・報告','事業用電気工作物の保安を確保するための保安規程について、基本的に適切な考え方はどれか。','工事・維持・運用の保安を管理する内容を定め、従事者は守る。',['販売価格だけを記載する規程である。','作成した後は誰も守る必要がない。','主任技術者が選任されていれば設備の保安管理は不要である。','設備が故障したときだけ記憶で内容を決めればよい。'],'保安規程は設備の工事、維持、運用に関する保安体制や管理を定める。単に文書を作るだけでなく、設備に即して実行することが重要。'),
      Q('保安・報告','電気工作物の事故に対する再発防止の検討として最も適切なものはどれか。','原因と影響を調査し、必要な設備・運用上の対策へ反映する。',['復旧さえすれば原因は一切確認しない。','すべての保護装置を取り外して事故を記録しない。','報告対象なら事実と異なる内容を記載してよい。','再発してから初めて予防策を考える。'],'事故の原因、保護の動作、設備状態などを調査し、保安規程や点検・設備の改善へ反映する。法令上の報告が必要な事故については所定の手続も行う。'),
      Q('保安・報告','電気保安のために行う「日常巡視」と「精密点検」の区別として適切なものはどれか。','日常巡視では運転中の外観などを確認し、精密点検では必要に応じ分解・測定・試験を行う。',['日常巡視では毎回すべての設備を分解する。','精密点検では測定や試験を一切行わない。','両者は点検目的も内容も必ず同じである。','精密点検を一度行えば以後の巡視は永久に不要になる。'],'点検の目的と深さ、設備の停止の要否などが異なる。異常の兆候を日常的にとらえ、計画的な点検や必要な整備につなげる。')])
    add('10',[
      Q('電線路・配線','電気使用場所の配線が弱電流電線などと接近・交差する場合、電気設備技術基準で防止を求める主な危険はどれか。','混触による感電又は火災。',['弱電流電線の色の変化だけ。','通信速度が必ず上がること。','光束の増加だけ。','電気料金が必ず安くなること。'],'配線が他の配線・弱電流電線などと接近・交差するときは、混触による感電又は火災のおそれがないように施設する。'),
      Q('電線路・配線','配線が水道管やガス管などと接近・交差する場合、電気設備技術基準に沿う考え方はどれか。','放電による損傷や、漏電・放電による感電・火災のおそれを防ぐ。',['水道管は必ず通常の負荷電流の帰路にする。','ガス管の近くでは絶縁を必ず除去する。','金属管に接触すればどの条件でも安全になる。','他の工作物への損傷は考慮しなくてよい。'],'他の工作物そのものの損傷と、その工作物を介した感電・火災の防止を考える。配線と他の工作物の関係に応じた施設が必要。'),
      Q('保安・報告','高圧受電設備で、遮断器が開いていることだけを根拠に直ちに導体へ触れてよいか。最も適切なものはどれか。','逆送や残留電荷も考慮し、定められた隔離・検電・放電等の手順を行う。',['遮断器の表示が開なら必ず無電圧なので直ちに触れる。','太陽光発電や蓄電池からの逆送は存在し得ない。','コンデンサの残留電荷は開放と同時に必ず消える。','接地線が1本あれば手順はすべて不要になる。'],'設備には別電源からの逆送や残留電荷の可能性がある。具体的作業は有資格者が設備の保安規程等に従って行い、表示だけで無電圧と判断しない。')])
    # Facility management B11: demand and load factors have different denominators.
    capacity,peak,energy=choose(r,[(100,60,720),(200,100,1800),(150,90,1080)])
    demand=peak/capacity*100; load=energy/24/peak*100
    common=f'設備容量{capacity}kWの需要家で、ある日の最大需要電力は{peak}kW、1日の使用電力量は{energy}kWhだった。'
    out += [('11a',N('施設管理計算',common+'(a) 需要率は何%か。',demand,[demand/2,demand*1.5,100,peak/capacity],'%',f'需要率=最大需要電力/設備容量×100={peak}/{capacity}×100={demand:g}%。')),
            ('11b',N('施設管理計算',common+'(b) 日負荷率は何%か。',load,[load*.8,load*1.2,100,energy/24/capacity*100],'%',f'平均需要電力={energy}/24={energy/24:g}kW。日負荷率=平均/最大×100={load:g}%。'))]
    iron,copper,ratio,hours=choose(r,[(100,800,.5,10),(150,1200,.75,8),(200,1600,.4,12)])
    total=iron+copper*ratio**2; kwh=total*hours/1000
    common=f'変圧器を定格電圧で運転し、無負荷損{iron}W、定格電流時の負荷損{copper}W、負荷率{ratio*100:g}%が{hours}時間一定で続いた。電圧変動等の影響を無視する。'
    out += [('12a',N('施設管理計算',common+'(a) この負荷率での全損失は何Wか。',total,[iron+copper*ratio,iron+copper,copper*ratio**2,total/2],'W',f'負荷損は電流の2乗に比例する。W={iron}+{copper}×{ratio:g}²={total:g}W。')),
            ('12b',N('施設管理計算',common+'(b) この時間内の全損失電力量は何kWhか。',kwh,[kwh/2,kwh*2,total/1000,kwh*1000],'kWh',f'損失電力{total/1000:g}kWに運転時間{hours}hを掛ける。W={total/1000:g}×{hours}={kwh:g}kWh。'))]
    power,pf=choose(r,[(80,.8),(90,.6),(120,.8)])
    reactive=power*math.sqrt(1-pf*pf)/pf; reduction=(1-pf*pf)*100
    common=f'有効電力{power}kW、遅れ力率{pf:g}の負荷について、進相コンデンサを並列接続して力率1に改善する。電源電圧、有効電力及び電源から負荷までの線路抵抗は一定とする。'
    out += [('13a',N('施設管理計算',common+'(a) 必要なコンデンサの進み無効電力は何kvarか。',reactive,[reactive/2,reactive*2,power,power/pf],'kvar',f'Qc=P tanφ={power}×√(1−{pf:g}²)/{pf:g}={reactive:g}kvar。')),
            ('13b',N('施設管理計算',common+'(b) 力率改善による線路抵抗損の減少率は何%か。',reduction,[pf*100,(1-pf)*100,pf*pf*100,reduction/2],'%',f'電流は改善前の{pf:g}倍。損失は電流の2乗に比例し、改善後は{pf*pf*100:g}%。減少率は(1−{pf:g}²)×100={reduction:g}%。'))]
    # Keep a factual basis date distinct from the future exam's legal cutoff.
    for _,q in out:
        if q['category'] != '施設管理計算':
            q['explanation']+='\n\n2026年10月17日に確認できた公開資料に基づくオリジナル問題です。本試験に適用する法令の基準日は公式受験案内に従ってください。'
    return out
